    "value": "def sequence_playlist(payload):\n    if not isinstance(payload, dict):\n        return normalize_tracklist(payload)\n    allowed = [\"tracks\", \"order\", \"allow_duplicates\"]\n    for key in sorted(payload):\n        if key not in allowed:\n            return {\"ok\": False, \"error\": \"unexpected key '\" + str(key) + \"'\"}\n    order = \"artist\"\n    if \"order\" in payload:\n        order = payload[\"order\"]\n        if order != \"artist\" and order != \"duration\":\n            return {\"ok\": False, \"error\": \"'order' must be 'artist' or 'duration'\"}\n    sub = {\"tracks\": payload[\"tracks\"] if \"tracks\" in payload else None}\n    if \"allow_duplicates\" in payload:\n        sub[\"allow_duplicates\"] = payload[\"allow_duplicates\"]\n    base = normalize_tracklist(sub)\n    if not base[\"ok\"]:\n        return base\n    tracks = base[\"tracks\"]\n    if order == \"artist\":\n        ordered = sorted(tracks, key=lambda t: t[\"artist\"].lower())\n    else:\n        ordered = sorted(tracks, key=lambda t: t[\"seconds\"])\n    return {\"ok\": True, \"order\": order, \"count\": base[\"count\"], \"total_seconds\": base[\"total_seconds\"], \"tracks\": ordered}"
