    "value": "def build_manifest(payload):\n    if not isinstance(payload, dict):\n        return sequence_playlist(payload)\n    allowed = [\"tracks\", \"order\", \"allow_duplicates\", \"title\", \"gap_seconds\"]\n    for key in sorted(payload):\n        if key not in allowed:\n            return {\"ok\": False, \"error\": \"unexpected key '\" + str(key) + \"'\"}\n    if \"title\" not in payload:\n        return {\"ok\": False, \"error\": \"'title' is required\"}\n    title = payload[\"title\"]\n    if not isinstance(title, str):\n        return {\"ok\": False, \"error\": \"'title' must be a string\"}\n    clean_title = \" \".join(title.split())\n    if clean_title == \"\":\n        return {\"ok\": False, \"error\": \"'title' must not be blank\"}\n    gap = 2\n    if \"gap_seconds\" in payload:\n        gap = payload[\"gap_seconds\"]\n        if isinstance(gap, bool) or not isinstance(gap, int):\n            return {\"ok\": False, \"error\": \"'gap_seconds' must be an integer\"}\n        if gap < 0:\n            return {\"ok\": False, \"error\": \"'gap_seconds' must not be negative\"}\n    sub = {\"tracks\": payload[\"tracks\"] if \"tracks\" in payload else None}\n    if \"order\" in payload:\n        sub[\"order\"] = payload[\"order\"]\n    if \"allow_duplicates\" in payload:\n        sub[\"allow_duplicates\"] = payload[\"allow_duplicates\"]\n    seq = sequence_playlist(sub)\n    if not seq[\"ok\"]:\n        return seq\n    tracks = seq[\"tracks\"]\n    if seq[\"order\"] == \"artist\":\n        tracks = sorted(tracks, key=lambda t: (t[\"artist\"].lower(), -t[\"seconds\"]))\n    entries = []\n    position = 0\n    start = 0\n    total = 0\n    for track in tracks:\n        position = position + 1\n        entries.append({\"position\": position, \"id\": track[\"id\"], \"title\": track[\"title\"], \"artist\": track[\"artist\"], \"seconds\": track[\"seconds\"], \"clock\": track[\"clock\"], \"start\": start, \"start_clock\": format_clock(start), \"explicit\": track[\"explicit\"]})\n        total = total + track[\"seconds\"]\n        start = start + track[\"seconds\"] + gap\n    count = len(tracks)\n    if count > 0:\n        total_seconds = total + gap * (count - 1)\n    else:\n        total_seconds = 0\n    return {\"ok\": True, \"title\": clean_title, \"order\": seq[\"order\"], \"count\": count, \"gap_seconds\": gap, \"total_seconds\": total_seconds, \"total_clock\": format_clock(total_seconds), \"entries\": entries}"
